import 'package:flutter/material.dart';
import 'package:portrai/src/feature/ai_image_gen/domain/use_case/_use_case.dart';
import 'package:portrai/src/feature/ai_image_gen/presentation/bloc/_bloc.dart';
import 'package:portrai/src/module_configurator/service_locator.dart';

/// Shows an image generated by Firebase AI from [sourceImageUrl], rendering
/// [fallback] while it loads and whenever generation is unavailable or fails.
///
/// Set [removeBackground] when the image is drawn over a custom backdrop; the
/// prompt must then ask for a plain white background.
class AiImageWidget extends StatelessWidget {
  const AiImageWidget({
    required this.sourceImageUrl,
    required this.fallback,
    this.prompt = AiImagePrompts.avatar,
    this.removeBackground = false,
    this.fit = BoxFit.cover,
    super.key,
  });

  final String sourceImageUrl;
  final Widget fallback;
  final String prompt;
  final bool removeBackground;
  final BoxFit fit;

  @override
  Widget build(BuildContext context) {
    return BlocProvider(
      key: ValueKey((sourceImageUrl, prompt, removeBackground)),
      create: (_) => appServiceLocator.get<AiImageBloc>()
        ..add(
          LoadImageEvent(
            sourceImageUrl: sourceImageUrl,
            prompt: prompt,
            removeBackground: removeBackground,
          ),
        ),
      child: BlocBuilder<AiImageBloc, AiImageState>(
        builder: (context, state) {
          return switch (state) {
            LoadedState(:final image) => Image.memory(
              image.bytes,
              fit: fit,
              gaplessPlayback: true,
              errorBuilder: (_, _, _) => fallback,
            ),
            LoadingState() || UnavailableState() => fallback,
          };
        },
      ),
    );
  }
}
